def gm(x, c, a, w):
    return a * np.exp(-(x - c) ** 2 / (2.0 * w * w))

def m1(x, b0, b1, b2, c, a, w):
    xc = x - x.mean()
    return b0 + b1 * xc + b2 * xc * xc - gm(x, c, a, w)

